'use strict';
const projects={
candor:{title:'Candor',category:'01 / MULTIMODAL RESEARCH',description:'An earnings-call research tool that connects generated report claims to timestamped transcript passages. Text sentiment and descriptive audio features offer different views of the same call.',stages:[['Audio','Earnings-call recordings enter two branches: faster-whisper creates timestamped transcript segments; librosa measures descriptive pitch, energy, pauses, and speaking rate.'],['Transcript + features','FinBERT labels financial sentiment at the segment level. Audio features describe the recording; they are not validated measures of stress or deception.'],['Cited report','Structured generation selects supplied passages for report claims. Citation checks verify exact passage and timestamp matches. Optional pgvector retrieval brings in earlier calls from the same company.'],['Source inspection','The React interface links claims to their source passages and seeks local audio when available. FastAPI serves the saved research artifacts.']],notes:'Current: transcription, sentiment, audio features, and cited reports. Still unfinished: verified speaker identity, per-executive historical baselines, and held-out outcome evaluation. Matching citations do not establish factual accuracy or financial predictiveness.',stack:'FASTER-WHISPER / FINBERT / LIBROSA / PGVECTOR / FASTAPI / REACT'},
reroute:{title:'ReRoute AI',category:'02 / DECISION SYSTEMS',description:'Travel recovery as an inspectable sequence: detect a disruption, trace its consequences, score alternatives, and apply a traveler-controlled policy before taking action.',stages:[['Monitor','A background monitor polls active trips. A disruption triggers the recovery orchestrator. Simulated flight data is the default; AirLabs is an optional provider.'],['Impact + alternatives','The system walks itinerary dependencies and scores replacement options using price, duration, reliability, and traveler preferences.'],['Policy gate','Deterministic thresholds and restrictions choose automatic execution, explicit traveler approval, or escalation. The LLM does not authorize spending.'],['Recovery + explanation','The orchestrator coordinates flight, hotel, transfer, and notification updates. WebSockets stream progress. Groq explains the existing decision, with a template fallback.']],notes:'JWT-scoped access resolves resources from the authenticated caller. Real provider availability depends on configuration; this portfolio makes no bookings or network requests. The policy study below is a simplified illustration.',stack:'FASTAPI / SQLALCHEMY / WEBSOCKETS / JWT / GROQ'},
eval:{title:'Evallq',category:'03 / LLM EVALUATION',description:'A framework for comparing model responses under the same prompt, with an independent LLM judge, persisted experiments, and visible token and cost accounting.',stages:[['Prompt + model selection','A prompt or batch dataset selects up to three models for a side-by-side experiment. The project includes integrations across several providers.'],['Parallel inference','ThreadPoolExecutor runs independent model calls concurrently. SHA-256 response caching avoids redundant requests.'],['Five-metric judge','A LLaMA judge scores correctness, relevance, faithfulness, completeness, and hallucination-free quality, returning structured scores and reasoning.'],['Experiment history','SQLAlchemy persists experiments to PostgreSQL. The interface supports comparisons, leaderboard views, and CSV exports.']],notes:'LLM-as-judge scores are model judgments, not ground truth. Judge bias and factual errors remain possible. The visual on the project tile is illustrative and does not represent measured model performance.',stack:'PYTHON / FASTAPI / POSTGRESQL / SQLALCHEMY / DOCKER'},
hunter:{title:'AI Failure Hunter',category:'04 / RELIABILITY ENGINEERING',description:'A small evidence-first tool that finds edge-case failures in Python functions, minimizes reproducible inputs, and exports regression tests.',stages:[['Candidate inputs','Deterministic boundary cases work without credentials. Optional hosted Gemma proposes additional candidates, validated against supported JSON parameter types.'],['Fresh worker','Every test runs in a fresh subprocess with a wall-clock timeout and resource limits, keeping state separate between cases.'],['Executable oracle','Sorting, sum, identity, non-negative, and must-not-raise checks provide explicit expectations. An exception without an oracle is suspected, not confirmed.'],['Minimize + export','Reproducible failures are reduced to smaller cases and exported as JSON evidence or a Python regression test. Local JSON storage preserves run history.']],notes:'The seeded sorting bug drops duplicates by using set(). A subprocess is not a complete security sandbox; the original tool is for trusted local code. This portfolio only explains the architecture and never executes submitted code.',stack:'PYTHON / STREAMLIT / FASTAPI / SUBPROCESS / GEMMA (OPTIONAL)'}
};
const $=s=>document.querySelector(s);
for(let i=0;i<57;i++){const bar=document.createElement('i');bar.style.setProperty('--h',`${18+Math.abs(Math.sin(i*.61))*Math.sin((i+1)/59*Math.PI)*155}px`);$('.wave-art').append(bar);}
const detail=$('#project-dialog');
function openProject(id){const p=projects[id];$('#detail-title').textContent=p.title;$('#detail-category').textContent=p.category;$('#detail-description').textContent=p.description;$('#detail-notes').textContent=p.notes;$('#detail-stack').textContent=p.stack;const flow=$('#architecture');flow.replaceChildren();p.stages.forEach(([label,description],i)=>{const b=document.createElement('button');b.textContent=`0${i+1} ${label}`;b.setAttribute('aria-pressed',String(i===0));b.onclick=()=>{flow.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed','true');$('#stage-info').textContent=description;};flow.append(b);});$('#stage-info').textContent=p.stages[0][1];detail.showModal();detail.scrollTop=0;}
document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>openProject(b.dataset.project));
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
const cost=$('#cost');cost.oninput=()=>{const n=Number(cost.value);$('#cost-value').textContent=`$${n.toLocaleString()}`;$('#decision-title').textContent=n<=200?'Auto approve':n<=600?'Ask the traveler':'Escalate to a human';$('#decision-text').textContent=n<=200?'Within the $200 automatic approval limit.':n<=600?'Above the automatic limit. Explicit approval is required.':'Above the $600 ceiling. Human intervention is required.';$('#decision-icon').textContent=n<=200?'↗':n<=600?'?':'!';};
const commands=[['Selected work',()=>location.hash='work'],['The policy laboratory',()=>location.hash='lab'],['About Kruthi',()=>location.hash='about'],...Object.entries(projects).map(([id,p])=>[p.title,()=>openProject(id)]),['Twist the thought',()=>{location.hash='';$('#morph').click();}],['Toggle motion',()=>$('#motion').click()]];
const palette=$('#command-dialog'),search=$('#command-search');function renderCommands(){const results=$('#command-results');results.replaceChildren();commands.filter(([label])=>label.toLowerCase().includes(search.value.toLowerCase())).forEach(([label,action])=>{const b=document.createElement('button');b.textContent=label+' ↗';b.onclick=()=>{palette.close();action();};results.append(b);});if(!results.children.length){const p=document.createElement('p');p.textContent='No matches. Try “work” or “Candor”.';results.append(p);}}
function openCommands(){if(detail.open)detail.close();search.value='';renderCommands();palette.showModal();search.focus();}
$('.command-trigger').onclick=openCommands;search.oninput=renderCommands;document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();palette.open?palette.close():openCommands();}});
palette.addEventListener('keydown',e=>{const list=[...$('#command-results').querySelectorAll('button')],i=list.indexOf(document.activeElement);if(e.key==='ArrowDown'){e.preventDefault();list[(i+1)%list.length]?.focus();}if(e.key==='ArrowUp'){e.preventDefault();if(i<=0)search.focus();else list[i-1].focus();}if(e.key==='Enter'&&document.activeElement===search){e.preventDefault();list[0]?.click();}});
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');let paused=motionQuery.matches;function updateMotion(){document.body.classList.toggle('motion-paused',paused);$('#motion').textContent=paused?'Resume motion':'Pause motion';window.dispatchEvent(new CustomEvent('motionchange',{detail:paused}));}$('#motion').onclick=()=>{paused=!paused;updateMotion();};motionQuery.addEventListener('change',e=>{paused=e.matches;updateMotion();});updateMotion();
